from __future__ import annotations

import importlib.metadata as importlib_metadata
import os
import warnings
from collections.abc import Iterable
from typing import TYPE_CHECKING, Final

if TYPE_CHECKING:
    from . import PydanticPluginProtocol


PYDANTIC_ENTRY_POINT_GROUP: Final[str] = 'pydantic'

# cache of plugins
_plugins: dict[str, PydanticPluginProtocol] | None = None
# return no plugins while loading plugins to avoid recursion and errors while import plugins
# this means that if plugins use pydantic
_loading_plugins: bool = False


def _should_disable_plugin(plugin_name: str) -> bool:
    """Check if a plugin should be disabled based on the PYDANTIC_DISABLE_PLUGINS environment variable.

    Args:
        plugin_name: The name of the plugin to check.

    Returns:
        True if the plugin should be disabled, False otherwise.
    """
    disable_plugins = os.environ.get('PYDANTIC_DISABLE_PLUGINS')
    if not disable_plugins:
        return False

    # Check for special values that disable all plugins
    if disable_plugins.lower() in ('__all__', '1', 'true'):
        return True

    # Check if this specific plugin is in the comma-separated list
    disabled_plugins = [p.strip() for p in disable_plugins.split(',')]
    return plugin_name in disabled_plugins


def get_plugins() -> Iterable[PydanticPluginProtocol]:
    """Load plugins for Pydantic.

    Inspired by: https://github.com/pytest-dev/pluggy/blob/1.3.0/src/pluggy/_manager.py#L376-L402
    """
    global _plugins, _loading_plugins

    # Check if all plugins should be disabled
    disable_plugins = os.environ.get('PYDANTIC_DISABLE_PLUGINS')
    if disable_plugins and disable_plugins.lower() in ('__all__', '1', 'true'):
        return ()

    if _loading_plugins:
        # this happens when plugins themselves use pydantic, we return no plugins
        return ()
    elif _plugins is None:
        _plugins = {}
        # set _loading_plugins so any plugins that use pydantic don't themselves use plugins
        _loading_plugins = True
        try:
            for dist in importlib_metadata.distributions():
                for entry_point in dist.entry_points:
                    if entry_point.group != PYDANTIC_ENTRY_POINT_GROUP:
                        continue
                    if entry_point.value in _plugins:
                        continue
                    # Skip this plugin if it's disabled via environment variable
                    if _should_disable_plugin(entry_point.name):
                        continue
                    try:
                        _plugins[entry_point.value] = entry_point.load()
                    except (ImportError, AttributeError) as e:
                        warnings.warn(
                            f'{e.__class__.__name__} while loading the `{entry_point.name}` Pydantic plugin, '
                            f'this plugin will not be installed.\n\n{e!r}'
                        )
        finally:
            _loading_plugins = False

    return _plugins.values()

